using TutorFlow.Api.Tests.Dobles;

namespace TutorFlow.Api.Tests.Seguridad;

public sealed class IpDeOrigenApiTests
{
    private const string Pregunta = "¿Cuál es la nota mínima para aprobar?";
    private const string Proxy = "10.0.0.5";
    private const string IpDelCliente = "203.0.113.7";
    private const int LimitePorMinuto = 60;

    private static Dictionary<string, string?> ConProxy(params string[] ips) =>
        ips.Select((ip, i) => ($"Proxy:IpsConfiables:{i}", (string?)ip)).ToDictionary();

    private static Dictionary<string, string?> ConProxyYTasa(params string[] ips)
    {
        var configuracion = ConProxy(ips);
        configuracion["Limites:PreguntasPorMinutoPorIp"] = LimitePorMinuto.ToString(System.Globalization.CultureInfo.InvariantCulture);
        return configuracion;
    }

    private static Dictionary<string, string> Xff(string valor) => new() { ["X-Forwarded-For"] = valor };

    private static string IpAuditada(FabricaApi fabrica) => fabrica.Auditoria.Eventos[^1].IpOrigen;

    private static async Task<RespuestaApi> Preguntar(FabricaApi fabrica, string conexion, Dictionary<string, string>? encabezados = null) =>
        await fabrica.PreguntarAsync("estudiante", "EST-001", Pregunta, conexion, encabezados);

    private static async Task<RespuestaApi> PreguntarHastaElLimite(FabricaApi fabrica, string conexion, Dictionary<string, string> encabezados)
    {
        RespuestaApi ultima = null!;
        for (var i = 0; i <= LimitePorMinuto; i++)
        {
            ultima = await Preguntar(fabrica, conexion, encabezados);
        }

        return ultima;
    }

    [Fact]
    [Trait("CA", "CA-13")]
    [Trait("ESC", "ESC-047")]
    [Trait("SEG", "SEG-19")]
    public async Task ESC_047_Sin_proxies_configurados_x_forwarded_for_se_ignora()
    {
        using var fabrica = new FabricaApi();

        var respuesta = await Preguntar(fabrica, Proxy, Xff(IpDelCliente));

        Assert.Equal(200, respuesta.Estado);
        Assert.Equal(Proxy, IpAuditada(fabrica));
    }

    [Fact]
    [Trait("CA", "CA-13")]
    [Trait("ESC", "ESC-047")]
    [Trait("SEG", "SEG-19")]
    public async Task ESC_047_Sin_proxies_la_peticion_cuenta_para_el_limite_de_la_conexion()
    {
        using var fabrica = new FabricaApi(configuracion: ConfiguracionDePrueba.TasaPorMinuto(LimitePorMinuto));
        RespuestaApi ultima = null!;

        for (var i = 1; i <= LimitePorMinuto + 1; i++)
        {
            ultima = await Preguntar(fabrica, Proxy, Xff($"203.0.113.{i}"));
        }

        Assert.Equal(429, ultima.Estado);
    }

    [Fact]
    [Trait("CA", "CA-13")]
    [Trait("ESC", "ESC-048")]
    [Trait("SEG", "SEG-19")]
    public async Task ESC_048a_Desde_un_proxy_de_confianza_la_ip_de_origen_es_la_de_x_forwarded_for()
    {
        using var fabrica = new FabricaApi(configuracion: ConProxy(Proxy));

        var respuesta = await Preguntar(fabrica, Proxy, Xff(IpDelCliente));

        Assert.Equal(200, respuesta.Estado);
        Assert.Equal(IpDelCliente, IpAuditada(fabrica));
    }

    [Fact]
    [Trait("CA", "CA-13")]
    [Trait("ESC", "ESC-048")]
    [Trait("SEG", "SEG-19")]
    public async Task ESC_048a_La_peticion_cuenta_para_el_limite_del_cliente_y_no_para_el_del_proxy()
    {
        using var fabrica = new FabricaApi(configuracion: ConProxyYTasa(Proxy));

        var ultima = await PreguntarHastaElLimite(fabrica, Proxy, Xff(IpDelCliente));
        var sinCabecera = await Preguntar(fabrica, Proxy);

        Assert.Equal(429, ultima.Estado);
        Assert.Equal(200, sinCabecera.Estado);
    }

    [Fact]
    [Trait("CA", "CA-13")]
    [Trait("ESC", "ESC-048")]
    [Trait("SEG", "SEG-19")]
    public async Task ESC_048b_Con_una_cadena_solo_cuenta_el_ultimo_valor()
    {
        using var fabrica = new FabricaApi(configuracion: ConProxy(Proxy));

        var respuesta = await Preguntar(fabrica, Proxy, Xff($"198.51.100.1, {IpDelCliente}"));

        Assert.Equal(200, respuesta.Estado);
        Assert.Equal(IpDelCliente, IpAuditada(fabrica));
    }

    [Theory]
    [InlineData("::ffff:10.0.0.5")]
    [InlineData("10.0.0.5")]
    [Trait("CA", "CA-13")]
    [Trait("ESC", "ESC-048")]
    [Trait("SEG", "SEG-19")]
    public async Task ESC_048c_La_conexion_en_formato_ipv4_mapeado_se_compara_como_ipv4(string conexion)
    {
        using var fabrica = new FabricaApi(configuracion: ConProxy(Proxy));

        var respuesta = await Preguntar(fabrica, conexion, Xff(IpDelCliente));

        Assert.Equal(200, respuesta.Estado);
        Assert.Equal(IpDelCliente, IpAuditada(fabrica));
    }

    [Fact]
    [Trait("CA", "CA-13")]
    [Trait("ESC", "ESC-048")]
    [Trait("SEG", "SEG-19")]
    public async Task ESC_048d_Sin_x_forwarded_for_se_conserva_la_ip_de_la_conexion()
    {
        using var fabrica = new FabricaApi(configuracion: ConProxy(Proxy));

        var respuesta = await Preguntar(fabrica, Proxy);

        Assert.Equal(200, respuesta.Estado);
        Assert.Equal(Proxy, IpAuditada(fabrica));
    }

    [Theory]
    [InlineData("EST-002")]
    [InlineData("203.0.113.7, abc")]
    [Trait("CA", "CA-13")]
    [Trait("ESC", "ESC-048")]
    [Trait("SEG", "SEG-19")]
    public async Task ESC_048e_Un_ultimo_valor_que_no_es_ip_conserva_la_ip_de_la_conexion(string valor)
    {
        using var fabrica = new FabricaApi(configuracion: ConProxy(Proxy));

        var respuesta = await Preguntar(fabrica, Proxy, Xff(valor));

        Assert.Equal(200, respuesta.Estado);
        Assert.Equal(Proxy, IpAuditada(fabrica));
        Assert.DoesNotContain(fabrica.Auditoria.Eventos, e => e.IpOrigen.Contains("EST-002", StringComparison.Ordinal));
    }

    [Fact]
    [Trait("CA", "CA-13")]
    [Trait("ESC", "ESC-048")]
    [Trait("SEG", "SEG-19")]
    public async Task ESC_048e_Forwarded_x_real_ip_y_x_forwarded_host_se_ignoran_siempre()
    {
        using var fabrica = new FabricaApi(configuracion: ConProxy(Proxy));
        var encabezados = new Dictionary<string, string>
        {
            ["Forwarded"] = "for=203.0.113.9",
            ["X-Real-IP"] = "203.0.113.9",
            ["X-Forwarded-Host"] = "evil.example",
            ["X-Forwarded-Proto"] = "https"
        };

        var respuesta = await Preguntar(fabrica, Proxy, encabezados);

        Assert.Equal(200, respuesta.Estado);
        Assert.Equal(Proxy, IpAuditada(fabrica));
        Assert.DoesNotContain(fabrica.Auditoria.Eventos, e => e.IpOrigen.Contains("203.0.113.9", StringComparison.Ordinal));
    }

    [Fact]
    [Trait("CA", "CA-13")]
    [Trait("ESC", "ESC-048")]
    [Trait("SEG", "SEG-19")]
    public async Task ESC_048e_Forwarded_y_x_real_ip_se_ignoran_tambien_sin_proxies_configurados()
    {
        using var fabrica = new FabricaApi();
        var encabezados = new Dictionary<string, string>
        {
            ["Forwarded"] = "for=203.0.113.9",
            ["X-Real-IP"] = "203.0.113.9",
            ["X-Forwarded-For"] = "203.0.113.9"
        };

        await Preguntar(fabrica, Proxy, encabezados);

        Assert.Equal(Proxy, IpAuditada(fabrica));
    }

    [Fact]
    [Trait("CA", "CA-13")]
    [Trait("ESC", "ESC-049")]
    [Trait("SEG", "SEG-19")]
    public async Task ESC_049_Una_conexion_fuera_de_la_lista_conserva_su_ip_y_su_propio_limite()
    {
        using var fabrica = new FabricaApi(configuracion: ConProxyYTasa(Proxy));

        var ultima = await PreguntarHastaElLimite(fabrica, "10.0.0.6", Xff(IpDelCliente));
        var desdeElProxy = await Preguntar(fabrica, Proxy, Xff(IpDelCliente));

        Assert.Equal(429, ultima.Estado);
        Assert.Equal(200, desdeElProxy.Estado);
        Assert.All(fabrica.Auditoria.Eventos.Take(LimitePorMinuto + 1), e => Assert.Equal("10.0.0.6", e.IpOrigen));
    }

    [Theory]
    [InlineData("127.0.0.1", true)]
    [InlineData("::1", true)]
    [InlineData("127.0.0.1", false)]
    [InlineData("::1", false)]
    [Trait("CA", "CA-13")]
    [Trait("ESC", "ESC-067")]
    [Trait("SEG", "SEG-19")]
    public async Task ESC_067_El_loopback_nunca_se_confia_implicitamente(string conexion, bool conProxyConfigurado)
    {
        var configuracion = conProxyConfigurado ? ConProxy(Proxy) : null;
        using var fabrica = new FabricaApi(configuracion: configuracion);

        var respuesta = await Preguntar(fabrica, conexion, Xff(IpDelCliente));

        Assert.Equal(200, respuesta.Estado);
        Assert.Equal(conexion, IpAuditada(fabrica));
    }

    [Fact]
    [Trait("CA", "CA-13")]
    [Trait("ESC", "ESC-068")]
    [Trait("SEG", "SEG-13")]
    public async Task ESC_068_Tras_el_proxy_cada_cliente_tiene_su_propio_limite()
    {
        using var fabrica = new FabricaApi(configuracion: ConProxyYTasa(Proxy));

        var ultima = await PreguntarHastaElLimite(fabrica, Proxy, Xff(IpDelCliente));
        var otroCliente = await Preguntar(fabrica, Proxy, Xff("203.0.113.8"));

        Assert.Equal(429, ultima.Estado);
        Assert.NotNull(ultima.Encabezado("Retry-After"));
        Assert.Equal(200, otroCliente.Estado);
    }

    [Fact]
    [Trait("CA", "CA-13")]
    [Trait("ESC", "ESC-069")]
    [Trait("SEG", "SEG-16")]
    public async Task ESC_069_Las_identidades_se_cuentan_por_la_ip_del_cliente_tras_el_proxy()
    {
        using var fabrica = new FabricaApi(configuracion: ConProxy(Proxy));
        string[] ids = ["EST-001", "EST-002", "EST-003", "EST-004"];
        var respuestas = new List<RespuestaApi>();

        foreach (var id in ids)
        {
            respuestas.Add(await fabrica.PreguntarAsync("estudiante", id, "¿Cuál es mi promedio?", Proxy, Xff(IpDelCliente)));
            fabrica.Reloj.Avanzar(TimeSpan.FromMinutes(1));
        }

        fabrica.Reloj.Avanzar(TimeSpan.FromMinutes(-1));
        respuestas.Add(await fabrica.PreguntarAsync("estudiante", "EST-005", "¿Cuál es mi promedio?", Proxy, Xff("203.0.113.8")));

        Assert.All(respuestas, r => Assert.Equal(200, r.Estado));
        var evento = Assert.Single(fabrica.Auditoria.MultiplesIdentidades);
        Assert.Equal(IpDelCliente, evento.IpOrigen);
        Assert.Equal(ids, evento.UsuarioIds);
        Assert.DoesNotContain(fabrica.Auditoria.MultiplesIdentidades, e => e.IpOrigen is Proxy or "203.0.113.8");
    }
}
using TutorFlow.Core.Asistente;
using TutorFlow.Core.Autorizacion;

namespace TutorFlow.Api.Tests.Seguridad;

public sealed class BloqueoDeIdentidadesApiTests
{
    private const string Pregunta = "¿Cuál es mi promedio?";
    private const string Conexion = "10.0.0.5";
    private const string IpDelCliente = "203.0.113.7";

    private static readonly Dictionary<string, string?> Bloqueo = new() { ["Limites:BloquearMultiplesIdentidades"] = "true" };

    private sealed class Sesion(FabricaApi fabrica)
    {
        private readonly DateTimeOffset _origen = fabrica.Reloj.AhoraUtc;

        public FabricaApi Fabrica { get; } = fabrica;

        public async Task<RespuestaApi> PreguntarEn(double minutos, string id, string conexion = Conexion, Dictionary<string, string>? encabezados = null)
        {
            Fabrica.Reloj.Fijar(_origen + TimeSpan.FromMinutes(minutos));
            return await Fabrica.PreguntarAsync("estudiante", id, Pregunta, conexion, encabezados);
        }

        public async Task RegistrarTresIdentidades()
        {
            foreach (var (id, minuto) in new[] { ("EST-001", 0), ("EST-002", 1), ("EST-003", 2) })
            {
                Assert.Equal(200, (await PreguntarEn(minuto, id)).Estado);
            }
        }
    }

    private static bool? Bloqueada(EventoMultiplesIdentidades evento) =>
        (bool?)evento.GetType().GetProperty("Bloqueada")?.GetValue(evento);

    private static void AfirmarRetryAfter(RespuestaApi respuesta, int segundos)
    {
        Afirmaciones.ProblemDetails(respuesta, 429);
        Assert.Equal(segundos.ToString(), respuesta.Encabezado("Retry-After"));
    }

    public static TheoryData<bool, string, string, string, string, int, int, string, int> FilasDeCa13 => new()
    {
        { false, "", "10.0.0.5", "203.0.113.7", "EST-004", 200, 1, "10.0.0.5", 0 },
        { true, "", "10.0.0.5", "203.0.113.7", "EST-004", 429, 1, "10.0.0.5", 420 },
        { true, "", "10.0.0.5", "203.0.113.7", "EST-001", 200, 0, "10.0.0.5", 0 },
        { true, "10.0.0.5", "10.0.0.5", "198.51.100.1, 203.0.113.7", "EST-004", 429, 1, "203.0.113.7", 420 }
    };

    [Theory]
    [MemberData(nameof(FilasDeCa13))]
    [Trait("CA", "CA-13")]
    [Trait("SEG", "SEG-16")]
    [Trait("SEG", "SEG-19")]
    public async Task CA_13_Suplantacion_por_ip_de_origen(bool bloqueo, string proxies, string conexion, string xff, string cuarta, int http, int eventos, string ip, int retryAfter)
    {
        var configuracion = new Dictionary<string, string?> { ["Limites:BloquearMultiplesIdentidades"] = bloqueo ? "true" : "false" };
        if (proxies.Length > 0)
        {
            configuracion["Proxy:IpsConfiables:0"] = proxies;
        }

        using var fabrica = new FabricaApi(configuracion: configuracion);
        var sesion = new Sesion(fabrica);
        var encabezados = new Dictionary<string, string> { ["X-Forwarded-For"] = xff };

        foreach (var (id, minuto) in new[] { ("EST-001", 0), ("EST-002", 1), ("EST-003", 2) })
        {
            await sesion.PreguntarEn(minuto, id, conexion, encabezados);
        }

        var respuesta = await sesion.PreguntarEn(3, cuarta, conexion, encabezados);

        Assert.Equal(http, respuesta.Estado);
        if (retryAfter > 0)
        {
            AfirmarRetryAfter(respuesta, retryAfter);
        }

        Assert.Equal(eventos, fabrica.Auditoria.MultiplesIdentidades.Count);
        Assert.Equal(4, fabrica.Auditoria.Eventos.Count);
        Assert.All(fabrica.Auditoria.Eventos, e => Assert.Equal(ip, e.IpOrigen));
        Assert.All(fabrica.Auditoria.MultiplesIdentidades, e => Assert.Equal(ip, e.IpOrigen));
        Assert.All(fabrica.Auditoria.MultiplesIdentidades, e => Assert.Equal(retryAfter > 0, Bloqueada(e)));
    }

    [Fact]
    [Trait("CA", "CA-13")]
    [Trait("ESC", "ESC-140")]
    [Trait("SEG", "SEG-16")]
    public async Task ESC_140_Sin_bloqueo_el_evento_lleva_bloqueada_false()
    {
        using var fabrica = new FabricaApi();
        var sesion = new Sesion(fabrica);
        await sesion.RegistrarTresIdentidades();

        var cuarta = await sesion.PreguntarEn(3, "EST-004");

        Assert.Equal(200, cuarta.Estado);
        var evento = Assert.Single(fabrica.Auditoria.MultiplesIdentidades);
        Assert.Equal(false, Bloqueada(evento));
    }

    [Fact]
    [Trait("CA", "CA-13")]
    [Trait("ESC", "ESC-141")]
    [Trait("SEG", "SEG-16")]
    public async Task ESC_141a_La_identidad_nueva_recibe_429_con_retry_after_420_y_evento_bloqueada_true()
    {
        using var fabrica = new FabricaApi(configuracion: Bloqueo);
        var sesion = new Sesion(fabrica);
        await sesion.RegistrarTresIdentidades();
        Assert.Empty(fabrica.Auditoria.MultiplesIdentidades);

        var cuarta = await sesion.PreguntarEn(3, "EST-004");

        AfirmarRetryAfter(cuarta, 420);
        var evento = Assert.Single(fabrica.Auditoria.MultiplesIdentidades);
        Assert.Equal(["EST-001", "EST-002", "EST-003", "EST-004"], evento.UsuarioIds);
        Assert.Equal(true, Bloqueada(evento));
    }

    [Fact]
    [Trait("CA", "CA-13")]
    [Trait("ESC", "ESC-141")]
    [Trait("SEG", "SEG-16")]
    public async Task ESC_141a_El_429_no_invoca_al_llm_ni_lee_notas_o_asistencia()
    {
        using var fabrica = new FabricaApi(configuracion: Bloqueo);
        var sesion = new Sesion(fabrica);
        await sesion.RegistrarTresIdentidades();
        var llamadasLlm = fabrica.Llm.Llamadas;
        var llamadasApi = fabrica.Api.Llamadas.Count;

        await sesion.PreguntarEn(3, "EST-004");

        Assert.Equal(llamadasLlm, fabrica.Llm.Llamadas);
        var nuevas = fabrica.Api.Llamadas.Skip(llamadasApi).ToList();
        Assert.DoesNotContain(nuevas, l => l.StartsWith("ObtenerNotas", StringComparison.Ordinal) || l.StartsWith("ObtenerAsistencia", StringComparison.Ordinal));
    }

    [Fact]
    [Trait("CA", "CA-13")]
    [Trait("ESC", "ESC-141")]
    [Trait("SEG", "SEG-16")]
    public async Task ESC_141a_Una_identidad_ya_registrada_se_atiende_con_llm_aunque_haya_otra_bloqueada()
    {
        using var fabrica = new FabricaApi(configuracion: Bloqueo);
        var sesion = new Sesion(fabrica);
        await sesion.RegistrarTresIdentidades();
        await sesion.PreguntarEn(3, "EST-004");
        var llamadasLlm = fabrica.Llm.Llamadas;

        var registrada = await sesion.PreguntarEn(4, "EST-001");

        Assert.Equal(200, registrada.Estado);
        Assert.Equal(llamadasLlm + 1, fabrica.Llm.Llamadas);
        Assert.Single(fabrica.Auditoria.MultiplesIdentidades);
    }

    [Fact]
    [Trait("CA", "CA-13")]
    [Trait("ESC", "ESC-141")]
    [Trait("SEG", "SEG-16")]
    [Trait("SEG", "SEG-19")]
    public async Task ESC_141b_El_bloqueo_es_por_ip_de_origen()
    {
        using var fabrica = new FabricaApi(configuracion: Bloqueo);
        var sesion = new Sesion(fabrica);
        await sesion.RegistrarTresIdentidades();

        var otraIp = await sesion.PreguntarEn(3, "EST-004", "10.0.0.6");

        Assert.Equal(200, otraIp.Estado);
        Assert.Empty(fabrica.Auditoria.MultiplesIdentidades);
    }

    [Fact]
    [Trait("CA", "CA-13")]
    [Trait("ESC", "ESC-141")]
    [Trait("SEG", "SEG-03")]
    [Trait("SEG", "SEG-16")]
    public async Task ESC_141c_Una_identidad_inexistente_es_403_identidad_invalida_y_no_429()
    {
        using var fabrica = new FabricaApi(configuracion: Bloqueo);
        var sesion = new Sesion(fabrica);
        await sesion.RegistrarTresIdentidades();

        var inexistente = await sesion.PreguntarEn(3, "EST-999");

        Afirmaciones.Negativa(inexistente, "estudiante");
        Assert.Equal(MotivoDenegacion.IdentidadInvalida, fabrica.Auditoria.Eventos[^1].MotivoDenegacion);
        Assert.Empty(fabrica.Auditoria.MultiplesIdentidades);
    }

    [Fact]
    [Trait("CA", "CA-13")]
    [Trait("ESC", "ESC-141")]
    [Trait("SEG", "SEG-16")]
    public async Task ESC_141c_Una_identidad_inexistente_no_ocupa_un_lugar_de_la_ventana()
    {
        using var fabrica = new FabricaApi(configuracion: Bloqueo);
        var sesion = new Sesion(fabrica);
        await sesion.PreguntarEn(0, "EST-001");
        await sesion.PreguntarEn(1, "EST-002");
        await sesion.PreguntarEn(2, "EST-999");

        var tercera = await sesion.PreguntarEn(3, "EST-003");

        Assert.Equal(200, tercera.Estado);
        Assert.Empty(fabrica.Auditoria.MultiplesIdentidades);
    }

    [Fact]
    [Trait("CA", "CA-13")]
    [Trait("ESC", "ESC-097")]
    [Trait("SEG", "SEG-16")]
    public async Task ESC_097_Sin_bloqueo_se_emite_un_evento_por_identidad_nueva_y_no_por_repeticion()
    {
        using var fabrica = new FabricaApi();
        var sesion = new Sesion(fabrica);
        var respuestas = new List<RespuestaApi>();

        foreach (var (id, minuto) in new[] { ("EST-001", 0), ("EST-002", 1), ("EST-003", 2), ("EST-004", 3), ("EST-005", 4), ("EST-004", 5) })
        {
            respuestas.Add(await sesion.PreguntarEn(minuto, id));
        }

        Assert.All(respuestas, r => Assert.Equal(200, r.Estado));
        var eventos = fabrica.Auditoria.MultiplesIdentidades;
        Assert.Equal(2, eventos.Count);
        Assert.Equal(["EST-001", "EST-002", "EST-003", "EST-004"], eventos[0].UsuarioIds);
        Assert.Equal(["EST-001", "EST-002", "EST-003", "EST-004", "EST-005"], eventos[1].UsuarioIds);
        Assert.All(eventos, e => Assert.Equal(false, Bloqueada(e)));
    }

