    {
        var escenario = new Escenario(bloqueo);
        escenario.RegistrarTres();

        var cuarta = escenario.Registrar("EST-004", 3);

        Assert.True(cuarta.Superado);
        Assert.True(cuarta.SuperacionNueva);
