        escenario.RegistrarTres();

        var renovada = escenario.Registrar("EST-001", 8);
        var nuevaEnElMinuto11 = escenario.Registrar("EST-004", 11);

        Assert.False(renovada.Superado);
        Assert.False(nuevaEnElMinuto11.Superado);
