        Assert.Equal(LlegadasAlLlm, llm.Llamadas);
        for (var i = 0; i < TotalDePeticiones; i++)
        {
            Assert.Equal(Ciclo[i % PeticionesPorCiclo].Esperado, respuestas[i].Estado);
        }

