        using var fabrica = new FabricaApi(configuracion: configuracion);
        RespuestaApi ultima = null!;

        for (var i = 0; i < 61; i++)
        {
            ultima = await fabrica.PreguntarEstudianteAsync("EST-001", Pregunta, "10.0.0.5");
        }

