        Assert.Equal([Cita(Entregada1), Cita(Entregada2)], entregadas.Order(StringComparer.Ordinal));
        Assert.NotEmpty(respuesta.Citas);
        Assert.All(respuesta.Citas, cita => Assert.Contains(cita, entregadas));
