$kind: http-request
order: 1000
method: POST
url: '{{baseUrl}}/api/asistente/preguntar'
headers:
  - key: Content-Type
    value: 'application/json'
  - key: X-Forwarded-For
    value: '203.0.113.200'
body:
  type: json
  content: |-
    {
      "pregunta": "¿Cuál es la nota mínima para aprobar?",
      "usuario": { "rol": "estudiante", "id": "EST-999" }
    }
scripts:
  - type: beforeRequest
    language: text/javascript
    code: |-
      const url = pm.variables.replaceIn("{{baseUrl}}/api/asistente/preguntar");
      const casos = [
        { rol: "estudiante", id: "EST-999", pregunta: "¿Cuál es mi promedio?" },
        { rol: "coordinador", id: "COORD-99", pregunta: "¿Qué puede ver otro coordinador?" },
        { rol: "estudiante", id: "EST-001", pregunta: "¿Cuáles son las notas de EST-002?" },
        { rol: "coordinador", id: "COORD-01", pregunta: "¿Qué puede ver otro coordinador?" }
      ];
      const estados = [];
      for (let i = 0; i < 100; i++) {
        const caso = casos[i % casos.length];
        const cuerpo = JSON.stringify({ pregunta: caso.pregunta, usuario: { rol: caso.rol, id: caso.id } });
        const respuesta = await pm.sendRequest({ url, method: "POST", header: { "Content-Type": "application/json", "X-Forwarded-For": "203.0.113." + (i + 1) }, body: { mode: "raw", raw: cuerpo } });
        estados.push(respuesta.code);
      }
      pm.variables.set("rafagaPrevia", JSON.stringify(estados));
  - type: afterResponse
    language: text/javascript
    code: |-
      pm.test("ESC-084d la petición 101 no recibe 429", () => pm.expect(pm.response.code).to.not.eql(429));
      pm.test("ESC-084d la petición 101 tiene el código que tendría sola (403 por identidad inválida)", () => pm.response.to.have.status(403));
      pm.test("ESC-084d las 100 peticiones previas no recibieron 429 ni 503", () => {
        const estados = JSON.parse(pm.variables.get("rafagaPrevia"));
        pm.expect(estados).to.have.lengthOf(100);
        pm.expect(estados.filter((e) => e === 429 || e === 503)).to.have.lengthOf(0);
      });
      pm.test("ESC-084d cada petición previa tiene el código que tendría sola (403)", () => {
        JSON.parse(pm.variables.get("rafagaPrevia")).forEach((e) => pm.expect(e).to.eql(403));
      });
      pm.test("ESC-084d la respuesta no incluye Retry-After", () => pm.expect(pm.response.headers.has("Retry-After")).to.be.false);
      pm.test("ESC-084d la respuesta 403 es una salida del contrato", () => {
        const cuerpo = pm.response.json();
        pm.expect(cuerpo).to.have.property("respuesta");
        pm.expect(cuerpo.usoDatosEstudiante).to.eql(false);
      });
