      const TEXTO_NEGATIVA = "No puedo compartir esa información: solo puedes consultar tus propios datos académicos.";
      pm.test("ESC-047 responde 403 y no 400 ni 500 pese a las cabeceras de reenvío", () => pm.response.to.have.status(403));
