        const texto = pm.response.text();
        ["203.0.113", "evil.example", "EST-002", "abc"].forEach((f) => pm.expect(texto).to.not.include(f));
      });
      pm.test("ESC-047 sin detalles internos ni stack trace", () => {
        const texto = pm.response.text();
        ["StackTrace", "   at ", "Exception", "System.", "Microsoft.", "TutorFlow."].forEach((f) => pm.expect(texto).to.not.include(f));
      });
      const claveCuerpo = "cuerpo403_estudiante";
      const previo = pm.collectionVariables.get(claveCuerpo);
      if (previo) {
        pm.test("ESC-047 el cuerpo 403 es idéntico al de cualquier otra denegación del rol (D-07, D-08)", () => {
          pm.expect(pm.response.text()).to.eql(previo);
        });
      }
